#!/usr/bin/env node
// semi-brand: builds a brand kit from its brand.json (docs/BRANDS.md). Runs inside the kit repo.
//   semi-brand build     validate brand.json, write dist/brand.css, dist/brand.json, BRAND.md, AGENTS.brand.md
//   semi-brand check     exit 1 when brand.json is invalid or a generated file is stale (the kit's CI / before a tag)
//   semi-brand preview   build, then serve the kit's own preview site locally (http://localhost:4600, --port N)
//   semi-brand site      build, then export the preview site as static files to .preview/out (GitHub Pages;
//                        SEMI_BRAND_BASE_PATH=/<repo> sets the path it is served under)
//   semi-brand storybook print the Semi Storybook "Brand preview" link for this brand.json (before a kit exists)
// The preview site template ships in @semi/ui (brand/preview) and is copied into .preview/ (gitignored) on each run,
// so a newer @semi/ui brings a newer preview.
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { generateBrand, SHADES } from "./generate.mjs";

const PREVIEW_URL = "https://hoanghuynh296.github.io/semi-nextjs-codebase/brand.html";
const pkgRoot = fileURLToPath(new URL("..", import.meta.url));
const readJson = (p) => JSON.parse(readFileSync(p, "utf8"));

/** next/font module for the brand's fonts: the variables next/font sets, as one className string. */
function fontsModule(fonts) {
  const id = (f) => f.nextFont.replace(/_(\w)/g, (_, c) => c.toUpperCase()).replace(/^\w/, (c) => c.toLowerCase());
  return [
    "// GENERATED by semi-brand: the brand's fonts (dist/brand.json). Do not edit.",
    `import { ${fonts.map((f) => f.nextFont).join(", ")} } from "next/font/google";`,
    "",
    ...fonts.map((f) => `const ${id(f)} = ${f.nextFont}({ subsets: ["latin", "vietnamese"], ${f.weight ? `weight: ${JSON.stringify(f.weight)}, ` : ""}variable: "${f.variable}" });`),
    "",
    `export const fontVariables = [${fonts.map((f) => `${id(f)}.variable`).join(", ")}].join(" ");`,
    "",
  ].join("\n");
}

/** Copy the preview site template into <kit>/.preview and add this brand's data (after a build). */
export function preparePreview(cwd) {
  const dir = join(cwd, ".preview");
  rmSync(join(dir, "app"), { recursive: true, force: true });
  cpSync(join(pkgRoot, "brand", "preview"), dir, { recursive: true });
  const kit = readJson(join(cwd, "dist", "brand.json"));
  cpSync(join(cwd, "dist", "brand.css"), join(dir, "app", "brand.css"));
  writeFileSync(join(dir, "app", "brand.json"), JSON.stringify(kit, null, 2) + "\n");
  writeFileSync(join(dir, "app", "fonts.js"), fontsModule(kit.fonts));
  return dir;
}

/** Run the kit's own Next.js (node_modules/.bin/next) in .preview. */
function next(cwd, args) {
  const bin = join(cwd, "node_modules", ".bin", process.platform === "win32" ? "next.cmd" : "next");
  if (!existsSync(bin)) {
    console.error("semi-brand: thiếu next trong brand kit. Chạy npm install (devDependencies: next, react, react-dom, tailwindcss, @tailwindcss/postcss).");
    return 2;
  }
  return spawnSync(bin, args, { cwd: join(cwd, ".preview"), stdio: "inherit", env: process.env }).status ?? 1;
}

/** brand.json → { files: { path: content }, result } (nothing written). */
export function buildKit(cwd) {
  const brand = readJson(join(cwd, "brand.json"));
  const tokens = readJson(join(pkgRoot, "tokens/tokens.json"));
  const styles = readJson(join(pkgRoot, "tokens/styles.json"));
  const version = readJson(join(pkgRoot, "package.json")).version;
  const result = generateBrand(brand, { tokens, styles, version });
  const files = {
    "dist/brand.css": result.css,
    "dist/brand.json": JSON.stringify({ $note: "GENERATED by semi-brand from brand.json — do not edit.", semiVersion: version, ...result.tokens, report: result.report, warnings: result.warnings }, null, 2) + "\n",
    "BRAND.md": brandMd(result, styles),
    "AGENTS.brand.md": agentsMd(result, styles),
  };
  return { files, result };
}

const swatches = (sc) => SHADES.map((s) => `| ${s} | \`${sc[s]}\` |`).join("\n");
const styleName = (styles, id) => styles.styles.find((s) => s.id === id)?.name ?? id;

function brandMd({ tokens: t, report, warnings }, styles) {
  const allowed = t.styles.allowed.map((id) => `${styleName(styles, id)}${id === t.styles.default ? " (mặc định)" : ""}`).join(", ");
  const font = (role) => t.fonts.find((f) => f.roles.includes(role)).family;
  return `<!-- GENERATED by semi-brand from brand.json — do not edit. -->
# ${t.name}: brand guideline

Bộ nhận diện của **${t.name}** trên Semi Design System. Mọi sản phẩm cài \`${t.package}\` và dùng đúng các giá trị này;
không định nghĩa màu, font hay style riêng trong sản phẩm. Muốn đổi: sửa \`brand.json\` trong repo brand rồi chạy
\`/semi-brand\` (xem \`@semi/ui/docs/BRANDS.md\`).

## Lựa chọn

| | |
|---|---|
| Màu chính | \`${t.primary[t.brandStep ?? 500]}\` (nằm ở \`primary-${t.brandStep ?? 500}\`) |
| Màu phụ | ${t.secondary ? `\`${t.secondary[t.secondaryStep ?? 500]}\` (nằm ở \`secondary-${t.secondaryStep ?? 500}\`)` : "không có"} |
| Màu trung tính | ${t.neutral === "tinted" ? "phủ theo màu chính" : "có sẵn của style"} |
| Style | ${allowed} |
| Font | ${font("sans")} (giao diện, nội dung) · ${font("display")} (tiêu đề, số KPI) |

## Màu chính (\`primary-*\`)

| Sắc độ | Mã |
|---|---|
${swatches(t.primary)}
${t.secondary ? `\n## Màu phụ (\`secondary-*\`)\n\n| Sắc độ | Mã |\n|---|---|\n${swatches(t.secondary)}\n` : ""}
## Dùng màu trong sản phẩm

| Việc | Token | Tối | Sáng |
|---|---|---|---|
| Nút chính | \`bg-accent\` + \`text-on-accent\` (hoặc \`Button variant="primary"\`) | \`${t.themes.dark["color-accent"]}\` / \`${t.themes.dark["color-on-accent"]}\` | \`${t.themes.light["color-accent"]}\` / \`${t.themes.light["color-on-accent"]}\` |
| Chữ, icon màu chính | \`text-accent-fg\` | \`${t.themes.dark["color-accent-fg"]}\` | \`${t.themes.light["color-accent-fg"]}\` |
| Viền focus, ô nhập đang gõ | \`ring-focus\`, \`border-focus\` | \`${t.themes.dark["color-accent-fg"]}\` | \`${t.themes.light["color-accent-fg"]}\` |
| Mục đang chọn (nền nhạt, viền) | \`bg-accent-subtle\`, \`border-accent-line\` | nhạt từ \`${t.themes.dark["color-accent-fg"]}\` | nhạt từ \`${t.themes.light["color-accent-fg"]}\` |
${t.secondary ? `| Chữ màu phụ | \`text-secondary-fg\` | \`${t.themes.dark["color-secondary-fg"]}\` | \`${t.themes.light["color-secondary-fg"]}\` |\n| Nền màu phụ (badge, điểm nhấn) | \`bg-secondary-solid\` + \`text-on-secondary\` | \`${t.themes.dark["color-secondary-solid"]}\` / \`${t.themes.dark["color-on-secondary"]}\` | \`${t.themes.light["color-secondary-solid"]}\` / \`${t.themes.light["color-on-secondary"]}\` |\n` : ""}
Không dùng \`primary-500/15\`, \`ring-primary-500/50\` … cho trạng thái: thang \`primary-*\` không đổi theo theme nên có
thể biến mất trên nền (\`semi-lint\`: \`accent-state-token\`). Nền, chữ và viền dùng token ngữ nghĩa (\`bg-panel\`, \`text-muted\`, \`border-line\` …); giá trị theo style, đã kiểm tra
đọc rõ. Màu trạng thái (thành công, lỗi, cảnh báo) giữ của Semi.

## Kiểm tra đọc rõ (chữ ≥ 4.5:1, viền và nút so với nền ≥ 3:1)

| Kiểm tra | Cặp | Tỉ lệ | Cần | |
|---|---|---:|---:|---|
${report.map((r) => `| ${r.check} | ${r.pair} | ${r.ratio.toFixed(2)} | ${r.min} | ${r.ok ? "đạt" : r.soft ? "lưu ý" : "**chưa đạt**"} |`).join("\n")}
${warnings.length ? `\n## Lưu ý\n\n${warnings.map((w) => `- ${w}`).join("\n")}\n` : ""}`;
}

function agentsMd({ tokens: t }, styles) {
  const allowed = t.styles.allowed.map((id) => `\`${id}\``).join(", ");
  return `<!-- semi-brand:start -->
## Brand: ${t.name} (\`${t.package}\`)

This product belongs to the **${t.name}** brand. Its colours, fonts and allowed styles come only from \`${t.package}\`
(\`node_modules/${t.package}/BRAND.md\`).

- Never define brand colours or override Semi tokens in this app (\`--color-primary-*\`, \`--semi-*\`, \`@theme\` colours,
  hex values): \`semi-lint\` blocks it (\`brand-override\`). Use the semantic tokens (\`bg-accent\`, \`text-accent-fg\`,
  \`bg-panel\` …)${t.secondary ? " and `secondary-*` / `text-secondary-fg` for the secondary colour" : ""}.
- Style: ${allowed} only (\`data-style\` on \`<html>\`, \`"style"\` in \`semi-lint.json\`, switch with \`/semi-style\`). No
  \`data-palette\`: the brand sets the neutrals.
- Fonts: ${t.fonts.map((f) => f.family).join(" + ")}, loaded with \`next/font\` in the root layout (\`${t.fonts.map((f) => f.variable).join("`, `")}\`).
- A change to the brand happens in the brand repo (\`/semi-brand\`), then \`/semi-update\` here.
<!-- semi-brand:end -->
`;
}

function main(argv) {
  const cmd = argv[0];
  const cwd = process.cwd();
  if (!["build", "check", "preview", "site", "storybook"].includes(cmd)) {
    console.log("usage: semi-brand build | check | preview [--port N] | site | storybook   (in a brand kit repo with brand.json)");
    return cmd ? 2 : 0;
  }
  if (!existsSync(join(cwd, "brand.json"))) {
    console.error("semi-brand: không thấy brand.json ở thư mục này (tạo brand kit bằng /semi-brand)");
    return 2;
  }
  if (cmd === "storybook") {
    const json = readFileSync(join(cwd, "brand.json"), "utf8");
    console.log(`${PREVIEW_URL}#brand=${Buffer.from(JSON.stringify(JSON.parse(json))).toString("base64url")}`);
    return 0;
  }
  let built;
  try {
    built = buildKit(cwd);
  } catch (e) {
    console.error(e.message);
    return 1;
  }
  const { files, result } = built;
  if (cmd === "check") {
    const stale = Object.entries(files).filter(([p, c]) => !existsSync(join(cwd, p)) || readFileSync(join(cwd, p), "utf8") !== c).map(([p]) => p);
    if (stale.length) console.error(`semi-brand: chưa sinh lại (chạy semi-brand build): ${stale.join(", ")}`);
    const failing = result.report.filter((r) => !r.ok && !r.soft);
    if (failing.length) console.error(`semi-brand: chưa đạt AA: ${failing.map((r) => r.check).join(", ")}`);
    if (!stale.length && !failing.length) console.log(`semi-brand: ${result.tokens.name} hợp lệ, file đã sinh khớp`);
    return stale.length || failing.length ? 1 : 0;
  }
  mkdirSync(join(cwd, "dist"), { recursive: true });
  for (const [p, c] of Object.entries(files)) writeFileSync(join(cwd, p), c);
  const ok = result.report.filter((r) => r.ok || r.soft).length;
  console.log(`semi-brand: ${result.tokens.name}: ${Object.keys(files).join(", ")} · đọc rõ ${ok}/${result.report.length} cặp đạt AA`);
  for (const w of result.warnings) console.log(`  lưu ý: ${w}`);
  const passed = result.report.every((r) => r.ok || r.soft);
  if (cmd === "build") {
    // A running preview (semi-brand preview) picks the new colours up right away.
    if (existsSync(join(cwd, ".preview", "app"))) preparePreview(cwd);
    return passed ? 0 : 1;
  }

  preparePreview(cwd);
  if (cmd === "site") {
    const status = next(cwd, ["build"]);
    if (status === 0) console.log(`semi-brand: trang preview tĩnh ở .preview/out${process.env.SEMI_BRAND_BASE_PATH ? ` (đường dẫn ${process.env.SEMI_BRAND_BASE_PATH})` : ""}`);
    return status;
  }
  const i = argv.indexOf("--port");
  const port = i > 0 && argv[i + 1] ? argv[i + 1] : process.env.PORT || "4600";
  console.log(`semi-brand: xem trước ${result.tokens.name} ở http://localhost:${port} (Ctrl+C để dừng)`);
  return next(cwd, ["dev", "--port", port]);
}

const isMain = process.argv[1] && /(semi-brand|brand[\\/]cli\.mjs)$/.test(process.argv[1]);
if (isMain) process.exit(main(process.argv.slice(2)));
